INSERT INTO "public"."songs" ("song_code", "title", "url", "lyrics", "created_at") VALUES
('b820', 'kaande mukut gillaa ra krus', 'https://www.nepalichristiansongs.net/songs/lyrics/nepali/kaande mukut gillaa ra krus - b820.html', '

